// Generated original query: Sentinel Hunt Workbench
// huntwb:time-scope
// huntwb:tenant-scope
// huntwb:workspace-scope
// huntwb:order=ascending
// huntwb:join-key=typed
// huntwb:entity-discriminator=immutable
// huntwb:dedup
// huntwb:aggregate-after-correlation
// huntwb:typed-identifiers
// huntwb:correlation-window=bounded
// huntwb:validity-check
// huntwb:missing-is-unknown
// huntwb:language=correlation
let start_time = {{start_time}};
let end_time = {{end_time}};
let workspace_id = {{workspace_id}};
let tenant_id = {{tenant_id}};
let correlation_window = {{correlation_window}};
let Stage1 = workspace(workspace_id).OfficeActivity
| where TimeGenerated between (start_time .. end_time)
| where isnotempty(OfficeObjectId)
| project Stage1Time=todatetime(TimeGenerated), WorkspaceScope=workspace_id, TenantScope=tenant_id, Stage1EntityId=tostring(OfficeObjectId), Stage1EventId=strcat_array(pack_array(tostring(Id)), "|"), Stage1EvidenceType="cloud file activity", Join1=tostring(UserId)
| where isnotempty(Stage1EntityId) and isnotempty(Stage1EventId)
| summarize arg_min(Stage1Time, *) by Stage1EventId;
let Stage1Rows = toscalar(Stage1 | count);
let Stage2 = workspace(workspace_id).SigninLogs
| where TimeGenerated between (start_time .. end_time)
| where tostring(AADTenantId) == tostring(tenant_id)
| where ResultType == "0"
| project Stage2Time=todatetime(TimeGenerated), WorkspaceScope=workspace_id, TenantScope=tenant_id, Stage2EntityId=tostring(UserId), Stage2EventId=strcat_array(pack_array(tostring(Id)), "|"), Stage2EvidenceType="authenticated account session", Join1=tostring(UserPrincipalName), Join2=tostring(UserPrincipalName)
| where isnotempty(Stage2EntityId) and isnotempty(Stage2EventId)
| summarize arg_min(Stage2Time, *) by Stage2EventId;
let Stage2Rows = toscalar(Stage2 | count);
let Stage3 = workspace(workspace_id).DeviceNetworkEvents
| where TimeGenerated between (start_time .. end_time)
| where isnotempty(DeviceId)
| project Stage3Time=todatetime(TimeGenerated), WorkspaceScope=workspace_id, TenantScope=tenant_id, Stage3EntityId=tostring(DeviceId), Stage3EventId=strcat_array(pack_array(tostring(DeviceId), tostring(ReportId), tostring(TimeGenerated)), "|"), Stage3EvidenceType="device network context", Join2=tostring(InitiatingProcessAccountUpn)
| where isnotempty(Stage3EntityId) and isnotempty(Stage3EventId)
| summarize arg_min(Stage3Time, *) by Stage3EventId;
let Stage3Rows = toscalar(Stage3 | count);
Stage1
| join kind=inner Stage2 on WorkspaceScope, TenantScope, Join1
| where Stage2Time between (Stage1Time .. Stage1Time + correlation_window)
| join kind=inner Stage3 on WorkspaceScope, TenantScope, Join2
| where Stage3Time between (Stage2Time .. Stage2Time + correlation_window)
| project Stage1Time, Stage1EntityId, Stage1EventId, Stage1EvidenceType, Stage1Rows, Stage2Time, Stage2EntityId, Stage2EventId, Stage2EvidenceType, Stage2Rows, Stage3Time, Stage3EntityId, Stage3EventId, Stage3EvidenceType, Stage3Rows, WorkspaceScope, TenantScope, EvidenceCompleteness="all required synthetic stages present", CorrelationStatement="correlated evidence; not proof of causation or compromise"
| order by Stage1Time asc
